# -*- coding: utf-8 -*-
# [260903 Phase1 M-2] _pmLoad: 프로그램마스터(_PM) 위에 programs 시트를 프로그램ID 로 오버레이. 끄기 window._PM_OVERLAY=false
# 실행: python3 tools/phase1_pmoverlay_260903.py  (먼저 backups/ 로 cp)
import io
P='public/standalone.html'
s=io.open(P,encoding='utf-8').read()
def one(a):
    assert s.count(a)==1, 'anchor not unique: %r (%d)'%(a[:60], s.count(a))
OV="/* ═══ [260903 Phase1 M-2] 프로그램 관리(programs 시트) → 프로그램마스터(_PM) 오버레이 ═══\n   원칙(청사진 §2): 관리자 폼이 쓰는 programs 시트가 정체성(이름·기간·장소·사업코드·구분)의 정본.\n   _PM(이력 시트 = v46 _json 봉인)은 같은 프로그램ID 가 있으면 그 열들을 programs 값으로 덮고, 없는 ID 는 새 행으로 추가한다.\n   재무 파생열(사업비·수입·수익률 …)은 이력 값을 그대로 둔다(Phase 4·5 에서 살아있는 계산으로 교체).\n   끄기: window._PM_OVERLAY=false (부팅 전). 대관(R… ID)·NO 빈 행은 PERFS 규칙과 같이 제외. */\nfunction _pmOverlayPrograms(pm, progs){\n  if(!Array.isArray(pm)||!Array.isArray(progs)||!progs.length)return {added:0,updated:0};\n  var byId={}; pm.forEach(function(r){ if(r&&r.id!=null)byId[String(r.id)]=r; });\n  function n8(v){ var s=String(v==null?'':v).trim(); var m=s.match(/^(\\d{4})[-./]?(\\d{2})[-./]?(\\d{2})/); if(m)return Number(m[1]+m[2]+m[3]); var n=Number(s); if(n>20000&&n<80000){ var d=new Date(Math.round((n-25569)*86400000)); return d.getUTCFullYear()*10000+(d.getUTCMonth()+1)*100+d.getUTCDate(); } return 0; }\n  function d8(v){ v=String(v||''); return v.length>=8?v.slice(4,6)+'.'+v.slice(6,8):''; }\n  var BUN={'공연':'공연','전시':'전시','예술교육':'교육','대관':'공연','기타':'기타'};\n  var added=0,updated=0;\n  progs.forEach(function(p){\n    var id=String(p['프로그램ID']||p['공연ID']||'').trim();\n    if(!id||/^R/i.test(id))return;                       // 대관(구글 캘린더 편입) 제외 — PERFS 규칙과 동일\n    if(p['NO']===''||p['NO']==null)return;\n    var ct=String(p['콘텐츠구분']||'').trim();\n    var bun=BUN[ct]||'기타';\n    var isRent=(ct==='대관');\n    var s=n8(p['시작일']),e=n8(p['종료일'])||s;\n    var sch=(function(){ var a=d8(s),b=d8(e); return (b&&b!==a)?(a+'~'+b):a; })();\n    var yr=s?Math.floor(s/10000):null;\n    var name=String(p['풀네임']||'').trim();\n    var short=String(p['줄임말']||'').trim();\n    var rc=parseInt(String(p['회차']||'').replace(/[^0-9]/g,''),10);\n    var fields={\n      명칭:name||null, 일정:sch||null, 장소:String(p['장소']||'').trim()||null,\n      사업코드:String(p['사업코드']||'').trim(),\n      _s:s||99999999, _e:e||0, _ps:n8(p['판매시작일'])||0, _hs:n8(p['홍보시작일'])||0,\n      _g2:String(p['장르']||p['구분']||'').trim()||null,\n      횟수:(rc>0?rc:null)\n    };\n    var cur=byId[id];\n    if(cur){\n      Object.keys(fields).forEach(function(k){ var v=fields[k]; if(v===null||v===undefined||v==='')return; cur[k]=v; });\n      if(short){ if(!Array.isArray(cur.별칭))cur.별칭=[]; if(cur.별칭.indexOf(short)<0)cur.별칭.push(short); }\n      cur.출처='programs';\n      updated++;\n    }else{\n      var gu=(bun==='교육')?'교육':(bun==='전시')?(isRent?'대관전시':'기획전시'):(isRent?'대관공연':'기획공연');\n      var rec={id:id,연도:yr,구분:gu,명칭:name,일정:sch,장소:fields.장소,횟수:fields.횟수,수강인원:null,출처:'programs',비고:null,앱_프로그램명:null,\n        사업비:null,수입:null,수익률:null,무료여부:null,사업비분할:null,수입분할:null,구분2:(isRent?'대관':'기획'),사업코드:fields.사업코드,분야:bun,\n        _s:fields._s,_e:fields._e,_ps:fields._ps,_hs:fields._hs,_st:'',_wg:0,_g2:fields._g2,별칭:(short?[short]:null),보고서명:null};\n      pm.push(rec); byId[id]=rec; added++;\n    }\n  });\n  try{ console.log('[260903 M-2] programs 오버레이',{added:added,updated:updated}); }catch(_e){}\n  return {added:added,updated:updated};\n}\n"
a1='function _pmLoad(){\n'
one(a1)
s=s.replace(a1, OV+'\n'+a1)
a2='_pmLoading=_pmSheetRows().then(function(list){'
one(a2)
s=s.replace(a2, "_pmLoading=_pmSheetRows().then(function(list){ /* [260903 M-2] programs 시트도 같이 받는다 */ return Promise.all([list,(window._PM_OVERLAY===false)?null:api('GET','/api/programs').catch(function(){return null;})]); }).then(function(res){ var list=res[0],_progRows=(res[1]&&res[1].programs)||[];")
a3='  _BPL=[];_PM_BY_ID={};_BPL_BY_KEY={};\n  _PM.forEach(function(r){_PM_BY_ID[String(r.id)]=r;});\n'
one(a3)
s=s.replace(a3, "  try{ _pmOverlayPrograms(_PM,_progRows); }catch(_oe){ console.warn('[260903 M-2] programs 오버레이 실패',_oe); }\n"+a3)
a4='    await loadPrograms();\n    updatePerfOpen();\n    renderCal();\n    await renderProgramList();\n    closeProgramForm();\n'
one(a4)
s=s.replace(a4, "    await loadPrograms();\n    try{ if(typeof _PM!=='undefined'&&_PM&&_PM.length){ var _pd=await api('GET','/api/programs'); _pmOverlayPrograms(_PM,(_pd&&_pd.programs)||[]); _PM_BY_ID={}; _PM.forEach(function(r){_PM_BY_ID[String(r.id)]=r;}); if(typeof _bizDeckDataVersion!=='undefined')_bizDeckDataVersion++; } }catch(_oe){ console.warn('[260903 M-2] 저장 후 오버레이',_oe); }   // [260903 M-2] 폼 저장 즉시 사업현황 레일 원천(_PM) 갱신\n    updatePerfOpen();\n    renderCal();\n    await renderProgramList();\n    closeProgramForm();\n")
io.open(P,'w',encoding='utf-8').write(s)
print('OK phase1 M-2 applied', len(s))
